            momf <- computeMOMF_parallel(TPM_matrix, sc_obj, 
                db, workers)
            deconv = cbind(deconv, momf)
        }
        return(deconv)
    }
    else {
        cat("\nNo methods to be calculated using variable signatures.")
        return(NULL)
    }
